import React, { Ref } from 'react';
import { useChipContext } from '../../ChipContext';
import { ChipLabelParagraph } from './ChipLabel.styles';
import { ChipLabelProps } from './ChipLabel.types';

export const ChipLabel = React.forwardRef(
  (
    { children, ...restProps }: ChipLabelProps,
    forwardedRef: Ref<HTMLParagraphElement>
  ): JSX.Element => {
    const chipContext = useChipContext();

    if (!chipContext) {
      // eslint-disable-next-line no-console
      console.warn(
        'Missing chip context, make sure that Chip.Label is being used as a child of Chip.Root'
      );
      return <></>;
    }

    const { disabled } = chipContext;
    return (
      <ChipLabelParagraph
        {...restProps}
        role="presentation"
        ref={forwardedRef}
        disabled={disabled}
        weight="medium"
      >
        {children}
      </ChipLabelParagraph>
    );
  }
);
